class Shape {
    String color;

    void displayColor() {
        System.out.println("Shape color: " + color);
    }
}

class Circle extends Shape {
    double radius;

    double getArea() {
        return Math.PI * radius * radius;
    }

    void displayCircleInfo() {
        // Uses inherited field 'color' and child field 'radius'
        System.out.println(color + " Circle with radius " + radius + ", Area: " + Math.round(getArea() * 100.0) / 100.0);
    }
}

public class ShapeDemo {
    public static void main(String[] args) {
        Circle c = new Circle();
        c.color = "Red";     // Inherited from Shape
        c.radius = 5.0;      // Defined in Circle

        c.displayColor();      // Inherited method
        c.displayCircleInfo(); // Subclass method
    }
}

