class Employee {
    String name;
    double basicSalary;

    void printBadge() {
        System.out.println("Badge -> Name: " + name + ", Base Salary: $" + basicSalary);
    }
}

class Manager extends Employee {
    int teamSize;

    void conductMeeting() {
        System.out.println(name + " is conducting a meeting with a team of " + teamSize + " members.");
    }
}

public class CompanyDemo {
    public static void main(String[] args) {
        // Verify the IS-A relationship:
        // A Manager IS-A Employee!
        Manager mgr = new Manager();
        mgr.name = "Sarah";
        mgr.basicSalary = 95000.0;
        mgr.teamSize = 8;

        // Inherited method from Employee superclass
        mgr.printBadge();

        // Specialized method from Manager subclass
        mgr.conductMeeting();
    }
}

